const $=s=>document.querySelector(s),fmt=n=>Math.round(n).toLocaleString('ja-JP')+' G',rnd=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const product=id=>PRODUCTS.find(p=>p.id===id),escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
