const tierUnlocked=(p,s=state)=>p.tier===0||p.tier===1&&s.equipment.shelf||p.tier===2&&s.equipment.case||p.tier===3&&s.equipment.cellar;
const unlockedProducts=(s=state)=>PRODUCTS.filter(p=>tierUnlocked(p,s));
function marketStockChance(routeId,p){return routeId==='market'&&p.tier===1?.22:routeId==='peddler'&&p.tier===1?.45:[1,.9,.65,.45][p.tier];}
function shuffleMarketItems(items){const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=rnd(0,i);[copy[i],copy[j]]=[copy[j],copy[i]];}return copy;}
function applyMarketBargains(s){
  for(const [id] of Object.entries(ROUTES)){
    const display=s.marketDisplay?.[id]||[];
    if(display.some(k=>s.market[id]?.[k]?.bargain))continue;
    const pool=display.filter(k=>s.market[id]?.[k]?.stock>0);
    if(!pool.length)continue;
    if(id!=='market'&&Math.random()>=0.65)continue;
    const pick=pool[rnd(0,pool.length-1)],m=s.market[id][pick];
    m.origPrice=m.price;
    m.price=Math.max(1,Math.round(m.price*0.82));
    m.bargain=true;
  }
}
// Five cards are chosen once and saved for the day. Sold-out cards retain their place.
function refreshMarket(s){s.market={};s.marketDisplay={};for(const [id,route] of Object.entries(ROUTES)){s.market[id]={};for(const p of PRODUCTS){const available=route.items.includes(p.id)&&tierUnlocked(p,s);s.market[id][p.id]={price:Math.max(1,Math.round(p.base*route.mult*(.9+Math.random()*.2))),stock:available&&Math.random()<marketStockChance(id,p)?rnd(1,p.tier>=2?2:4):0,equipmentLocked:route.items.includes(p.id)&&!tierUnlocked(p,s),bargain:false};}s.marketDisplay[id]=shuffleMarketItems(route.items.filter(key=>s.market[id][key]?.stock>0)).slice(0,5);if(!s.marketDisplay[id].length){const unlocked=shuffleMarketItems(route.items.filter(key=>tierUnlocked(product(key),s)));if(unlocked.length){const key=unlocked[0],p=product(key);s.market[id][key].stock=rnd(1,p.tier>=2?2:4);s.marketDisplay[id].push(key);}}}applyMarketBargains(s);}
// Older saves have market stocks but no selected-card list. Reconstruct without another draw.
function restoreMarketDisplay(s){s.marketDisplay={};for(const [id,route] of Object.entries(ROUTES)){const available=route.items.filter(key=>tierUnlocked(product(key),s)&&s.market[id]?.[key]?.stock>0);s.marketDisplay[id]=available.sort((a,b)=>{const rank=key=>{let hash=0;for(const c of `${s.day}:${id}:${key}`)hash=((hash<<5)-hash+c.charCodeAt(0))|0;return hash>>>0;};return rank(a)-rank(b);}).slice(0,5);}}
