  lot.qty--;state.display[p.id]=Math.max(0,displayBefore-1);state.inventory=state.inventory.filter(x=>x.qty>0);state.cash+=totalEarned;state.sales+=totalEarned;state.cogs+=lot.cost;state.report.sales+=totalEarned;state.report.cogs+=lot.cost;const activeBoom=demandBoomFor(),demandNotes=[df.popular?'本日人気':null,activeBoom?'ブーム期間中':null,df.boom?'ブーム対象':null,qualityBonus?`極上A +${fmt(qualityBonus)}`:null,counterTip+repTip?`心付け +${fmt(counterTip+repTip)}`:null].filter(Boolean);state.report.lines.push(`${customerForStep(step).name}：${p.name}（品質${lot.quality}）を${fmt(totalEarned)}で販売。${demandNotes.length?'【'+demandNotes.join('・')+'】':''}`);record(`${p.name}を${fmt(totalEarned)}で販売（原価${fmt(lot.cost)}）`);
  state.unitsSold++;state.soldById[p.id]=(state.soldById[p.id]||0)+1;state.salesHistory.push({saleId:++state.saleSerial,day:state.day,id:p.id,quality:lot.quality,known:lot.known,cost:lot.cost,price:totalEarned,returned:false,popularAtSale:df.popular,boomActiveAtSale:!!activeBoom,boomAtSale:df.boom});
  let milestoneEarned=0;const boomSalesToday=state.salesHistory.filter(x=>x.day===state.day&&!x.returned&&(x.popularAtSale||x.boomAtSale)).length;
  if(boomSalesToday>=DEMAND_PRICE_BONUS.milestoneCount&&!state.report.boomMilestonePaid){state.report.boomMilestonePaid=true;milestoneEarned=DEMAND_PRICE_BONUS.milestoneBonus;state.cash+=milestoneEarned;state.eventIncome=(state.eventIncome||0)+milestoneEarned;state.report.lines.push(`【流行繁盛ボーナス】流行品${boomSalesToday}点販売達成！ご祝儀＋${fmt(milestoneEarned)}`);record(`流行繁盛ボーナス：＋${fmt(milestoneEarned)}`);}
  s.upsell=null;
  if((state.speedMode==='normal'||state.autoPaused)&&!state.report.counterEventDone&&Math.random()<.3){const extras=state.shelfSlots.filter(id=>id&&id!==p.id&&tierUnlocked(product(id))&&displayed(id)>0);if(extras.length){const eid=extras[rnd(0,extras.length-1)],eLot=state.inventory.find(x=>x.id===eid&&x.qty>0);if(eLot){s.upsell={productId:eid,price:Math.max(1,Math.round(state.prices[eid]*demandPriceBonus(eid))),lotKey:{id:eLot.id,quality:eLot.quality,cost:eLot.cost,known:eLot.known}};state.report.counterEventDone=true;}}}
