function rejectForAuto(){const s=state.service,step=s?.queue[s.index];if(!step||s.stage!=='offer'||step.canBuy)return;const p=product(step.productId);state.report.lines.push(step.reason==='empty'?`${p.name}を探す客が来たが、品切れだった。`:`${p.name}は値段が合わず売れなかった。`);say(step.reason==='empty'?'empty':'reject',step.reason==='empty'?'worried':'angry');s.stage='reaction';s.reaction=step.reason==='empty'?'品切れでお売りできませんでした。':'今回は価格が折り合いませんでした。';playSE('decline');save();render();}
function clearAutoTimer(){if(autoTimer!==null){window.clearTimeout(autoTimer);autoTimer=null;}}
function scheduleAuto(){clearAutoTimer();if(tab!=='shop'||state.phase!=='serving'||state.speedMode==='normal'||state.autoPaused||state.activeEvent||!state.service)return;const delay=state.speedMode==='x4'?(state.service.stage==='reaction'?330:SALES_SPEED.x4):(state.service.stage==='reaction'?780:SALES_SPEED.x2);autoTimer=window.setTimeout(()=>{autoTimer=null;autoTick();},delay);}
function autoTick(){if(tab!=='shop'||state.phase!=='serving'||state.speedMode==='normal'||state.autoPaused||state.activeEvent||!state.service)return;const s=state.service;if(s.stage==='offer'){const step=s.queue[s.index];if(step.canBuy){if(!findLot(step)){step.canBuy=false;step.reason='empty';save();}else{sell();return;}}rejectForAuto();}else advance();}
function setSpeed(mode){if(state.phase!=='serving'||!Object.prototype.hasOwnProperty.call(SALES_SPEED,mode))return;state.speedMode=mode;state.autoPaused=false;playSE('ui');save();render();}
function toggleAutoPause(){if(state.phase!=='serving'||state.speedMode==='normal')return;state.autoPaused=!state.autoPaused;playSE('ui');save();render();}
// Future story events may set activeEvent and clear it when choices are complete.
function setActiveEvent(event){state.activeEvent=event||null;save();render();}
function closeDay(){if(state.phase!=='serving')return;clearAutoTimer();state.phase='closed';state.service=null;if(state.report.sales===0)say('zero','worried');else if(state.report.sales-state.report.cogs<0)say('loss','worried');else say('closed','proud');record(`閉店：売上${fmt(state.report.sales)}／粗利益${fmt(state.report.sales-state.report.cogs)}`);speakStockWarning();playSE('closeDay');save();render();}
function fastForward(confirmed=false){if(state.phase!=='serving')return;if(!confirmed){closeModal();$('#modal').innerHTML='<div class="modal" role="dialog" aria-modal="true" aria-labelledby="ff-title"><button class="btn small close" data-act="close">閉じる ×</button><h2 id="ff-title">残りのお客様を見送って閉店</h2><p>残りのお客様は販売せずに退店します。閉店までスキップしますか？</p><div class="actions"><button class="btn primary" data-act="fastforward-confirm">見送って閉店する</button><button class="btn" data-act="close">戻る</button></div></div>';$('#modal').classList.remove('hidden');$('#modal .btn.primary')?.focus();playSE('modalOpen');if(typeof GUIDE!=='undefined')GUIDE.sync();return;}closeModal();const s=state.service;for(let i=s.index;i<s.queue.length;i++){const step=s.queue[i];state.report.lines.push(`${customerForStep(step).name}：接客を見送った。`);}closeDay();}
function nextDay(){if(state.phase!=='closed'||state.finished||state.activeEvent)return;if(state.day>=RULES.days&&!state.free){showFinalSettlement();return;}const prevSales=state.report?.sales||0,prevGross=state.report?(state.report.sales-state.report.cogs):0;if(prevSales>0&&prevGross>0)state.profitStreak=(state.profitStreak||0)+1;else state.profitStreak=0;state.day++;bulkDisplayNotice='';state.phase='prepare';state.report=null;state.service=null;refreshMarket(state);demandAdvance(state);const repNow=reputationInfo(state),rankedUp=repNow.level>(state.lastReputationLevel||1);if(rankedUp)state.lastReputationLevel=repNow.level;let orderNotice='';if(state.specialOrder&&state.day>state.specialOrder.expiresDay){record(`特注期限切れ：${product(state.specialOrder.productId).name}`);state.specialOrder=null;state.nextOrderDay=state.day+rnd(2,3);}if(!state.specialOrder&&state.day>=(state.nextOrderDay||3)&&!state.finished&&state.day<RULES.days){state.specialOrder=createSpecialOrder(state);if(state.specialOrder){const op=product(state.specialOrder.productId);orderNotice=`【特注依頼】${state.specialOrder.clientName}様から「${op.name} ×${state.specialOrder.qty}」の特注（報酬${fmt(state.specialOrder.rewardPrice)}・第${state.specialOrder.expiresDay}日まで）が届きましたわ！`;}}const headline=demandDailyHeadline(state);if(headline)state.dialogue={key:'demand-'+headline.kind,text:headline.text,mood:headline.kind==='end'&&headline.text.includes('逃して')?'worried':'happy'};else if(rankedUp)state.dialogue={key:'rank-up',text:`【評判上昇】当店の評判が「Lv.${repNow.level} ${repNow.title}」になりましたわ！ ${repNow.perkText} ですのよ！`,mood:'happy'};else if(orderNotice)state.dialogue={key:'special-order',text:orderNotice,mood:'proud'};else say('prepare','proud',state.day%2);speakStockWarning();const evStarted=maybeStartNormalEvent();if(!evStarted)playSE(headline&&(headline.kind==='start'||headline.kind==='forecast')?'boomStart':rankedUp?'rankUp':'nextDay');if(state.day===60&&!state.lateAdviceSeen){state.lateAdviceSeen=true;state.lateAdvicePending=true;}save();render();}
const DEBT_CELEBRATION_LINES=[
 '……ついに、借金を返し終えましたわ！',
 'おーっほっほ！ これでようやく、この店は名実ともに私のものですわね！',
 '……けれど、ここで商売を終えるなんて、もったいありませんわ',
 'せっかく手に入れた私のお店ですもの。もっと立派にしてみせますわ！',
 '財を蓄え、珍品を鑑定し、その価値を誰よりも見抜く……',
 '目指すはただ一つ！',
 '伝説の珍品商ですわ！'
];
function repay(requested){if(state.phase==='serving'||state.finished||state.debt<=0)return;const amount=Math.min(requested,state.cash,state.debt);if(amount<=0)return;state.cash-=amount;state.debt-=amount;state.repaid+=amount;record(`${fmt(amount)}返済。残債${fmt(state.debt)}`);say('repaid','proud');if(state.debt===0){ensureAnalytics().debtPaidDay??=state.day;if(!state.debtCelebrationSeen){state.debtCelebrationSeen=true;if(state.day<RULES.days||state.free)state.debtCelebration={index:0};}}playSE(state.debt===0?'debtCleared':'repay');save();render();}
function advanceDebtCelebration(){if(!state.debtCelebration)return;state.debtCelebration.index++;if(state.debtCelebration.index>=DEBT_CELEBRATION_LINES.length){state.debtCelebration=null;state.dialogue={key:'goal-unlocked',text:'新たな経営目標が解放されました。伝説の珍品商を目指そう！ 詳しい達成条件は帳簿で確認できます。',mood:'happy'};}playSE('dialogue');save();render();}
function equip(id){const e=EQUIPMENT[id];if(!e||state.equipment[id]||e.requires&&!state.equipment[e.requires]||state.cash<e.price||state.finished||state.phase==='serving'&&state.service?.stage!=='reaction')return;state.cash-=e.price;state.expense+=e.price;state.equipment[id]=true;extendMarketForEquipment(state);record(`${e.name}を設置（${fmt(e.price)}）`);if(['shelf','case','cellar'].every(key=>state.equipment[key]))ensureAnalytics().equipmentCompletedDay??=state.day;say('bought','happy');playSE('equip');save();render();}
function unlockRoute(id){const r=ROUTES[id];if(!r||state.routes[id]||state.cash<r.price||state.finished||state.phase==='serving'&&state.service?.stage!=='reaction')return;state.cash-=r.price;state.expense+=r.price;state.routes[id]=true;routeId=id;extendMarketForEquipment(state);record(`${r.name}の仕入れルートを開拓（${fmt(r.price)}）`);playSE('unlockRoute');save();render();}
// Only the final, already-closed day is eligible. Codex counts valid product IDs, not arbitrary keys.
function registeredCodexCount(s=state){return PRODUCTS.reduce((n,p)=>n+(s.codex?.[p.id]===true?1:0),0);}
function endingFor(s=state){if(s.debt>0)return 'ending_01';if(s.cash>=ENDING_GOALS.legendCash&&ENDING_GOALS.majorEquipment.every(id=>s.equipment?.[id])&&registeredCodexCount(s)>=ENDING_GOALS.legendCodex)return 'ending_04';if(s.cash>=ENDING_GOALS.merchantCash)return 'ending_03';return 'ending_02';}
function showFinalSettlement(){
 if(state.finished||state.day!==RULES.days||state.phase!=='closed'||state.activeEvent)return;
 const payable=Math.min(state.cash,state.debt);
 $('#modal').innerHTML=`<div class="modal final-settlement" role="dialog" aria-modal="true" aria-labelledby="final-settlement-title"><h2 id="final-settlement-title">Day 90・最終精算</h2><p>最終返済を行ってから結果を確定できます。確定後は営業へ戻れません。</p><p>手元現金：<strong>${fmt(state.cash)}</strong></p><p>借金残高：<strong>${fmt(state.debt)}</strong></p><p>今回返済できる額：<strong>${fmt(payable)}</strong></p><p>全額返済後の残債：<strong>${fmt(state.debt-payable)}</strong> ／ 手元現金：<strong>${fmt(state.cash-payable)}</strong></p><div class="actions">${payable?`<button class="btn primary" data-act="final-repay">${fmt(payable)}を返済する</button>`:''}<button class="btn" data-act="final-confirm">この状態で最終精算を確定</button><button class="btn" data-act="close">戻る</button></div>${state.debt>0?'<p class="hint">借金が残っている状態で確定すると「店没収」になります。</p>':''}</div>`;
 $('#modal').classList.remove('hidden');playSE('modalOpen');if(typeof GUIDE!=='undefined')GUIDE.sync();
}
function finalRepay(){if(state.finished||state.day!==RULES.days||state.phase!=='closed'||state.activeEvent)return;repay(state.cash);showFinalSettlement();}
function finish(confirmed=false){
 if(state.finished){if(state.ending)showEnding();return;}
 if(state.day!==RULES.days||state.phase!=='closed'||state.free||state.activeEvent)return;
 if(!confirmed){$('#modal').innerHTML=`<div class="modal final-settlement" role="dialog" aria-modal="true" aria-labelledby="final-confirm-title"><button class="btn small close" data-act="close">閉じる ×</button><h2 id="final-confirm-title">最終精算を確定しますか？</h2><p>借金残高：<strong>${fmt(state.debt)}</strong></p><p>最終所持金：<strong>${fmt(state.cash)}</strong></p><p class="hint">確定後は営業に戻れません。</p><div class="actions"><button class="btn primary" data-act="final-confirm-yes">最終精算を確定する</button><button class="btn" data-act="close">戻る</button></div></div>`;$('#modal').classList.remove('hidden');$('#modal .btn.primary')?.focus();playSE('modalOpen');if(typeof GUIDE!=='undefined')GUIDE.sync();return;}
 closeModal();
 const id=endingFor(state);
 state.ending={id,stage:'still',day:state.day,cash:state.cash,debt:state.debt,codexCount:registeredCodexCount(state),sales:state.sales,repaid:state.repaid,equipmentCount:['shelf','case','cellar'].filter(key=>state.equipment[key]).length};
 state.finished=true;state.won=id!=='ending_01';
 playSE(id==='ending_01'?'endingBad':'endingGood');
 save();render();showEnding();
}
function resultAnalyticsHtml(){
 const history=completedSales();
 const volume=Object.entries(state.soldById||{}).filter(([id,n])=>product(id)&&n>0).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0];
 const profits=new Map();for(const sale of history)profits.set(sale.id,(profits.get(sale.id)||0)+(sale.price-sale.cost));
 const mostProfit=[...profits].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0];
 const demandStats=demandSaleStats(history),partial=demandStats.known<demandStats.total||history.length<(state.unitsSold||0);
 const activeCount=demandStats.active,boomTargetCount=demandStats.target,popCount=demandStats.popular;
 const logs=state.log||[],debtLine=logs.find(line=>/返済。残債0 G/.test(line)),debtDay=debtLine?/第(\d+)日/.exec(debtLine)?.[1]:null;
 const equipmentDays=['shelf','case','cellar'].map(id=>{const entry=logs.find(line=>line.includes(`${EQUIPMENT[id].name}を設置`));return entry?Number(/第(\d+)日/.exec(entry)?.[1]):null;});
 const completed=state.analytics?.equipmentCompletedDay??(equipmentDays.every(Number.isFinite)?Math.max(...equipmentDays):null),paidDay=state.analytics?.debtPaidDay??debtDay;
 const outside=state.analytics?.outsideSales??0,incomplete=state.analytics?.legacyIncomplete!==false,storeSales=state.sales-outside;
 return `<section class="ending-review" aria-label="90日間の経営振り返り"><h3>経営の振り返り</h3><p>最多販売：${volume?escapeHtml(product(volume[0]).name)+'（'+volume[1]+'点）':'記録なし'}</p><p>最多粗利益：${mostProfit?escapeHtml(product(mostProfit[0]).name)+'（'+fmt(mostProfit[1])+'）':'記録なし'}</p><p>人気商品としての販売：${demandStats.known?popCount+'点':'記録なし'}</p><p>ブーム期間中の販売：${demandStats.known?activeCount+'点（対象品 '+boomTargetCount+'点）':'記録なし'}</p><p>借金完済日：${paidDay?'Day '+paidDay:'記録なし'} ／ 主要設備完成日：${completed?'Day '+completed:'記録なし'}</p><h3>売上の照合</h3><p>全取引の累計売上：${fmt(state.sales)}</p><p>${incomplete?'Ver.69以降の店頭外取引・返品調整（記録分）':'店頭営業売上'}：${fmt(incomplete?outside:storeSales)}</p>${incomplete?'<small>旧セーブの店頭外取引は全件を復元できないため、店頭営業売上の確定値は表示しません。</small>':`<p>店頭外取引・返品調整：${fmt(outside)}（店頭営業売上との差額）</p>`}${partial?'<small>※需要別集計は記録がある販売分のみ。旧データの不足分は推測していません。</small>':''}</section>`;
}
function showEnding(){
 if(!state.ending)return;
 const result=state.ending,id=result.id,title=ENDING_NAMES[id];
 clearAutoTimer();clearOpeningTimer();stopOpeningBgm();openingRun=null;closeModal();
 if(result.stage==='still')BGM.play(id);else BGM.stop(1000);
 const screen=$('#opening');screen.classList.remove('hidden');
 const stillUrl=endingStillPath(id);
 if(result.stage==='still'){
  const manuscript=ENDING_SCRIPTS[id];if(!manuscript)throw Error(`Missing formal ending manuscript: ${id}`);
  result.line=Math.max(0,Math.min(manuscript.lines.length-1,result.line||0));
  const [speaker,raw]=manuscript.lines[result.line],full=raw.replace('{debt}',Math.round(result.debt).toLocaleString('ja-JP'));
  screen.innerHTML=`<div class="opening-frame"><div class="opening-art loaded">${stillUrl?`<img class="opening-still-img" src="${escapeHtml(stillUrl)}" alt="" decoding="sync">`:''}</div><div class="opening-stage ending-stage"><div class="opening-top"><span class="scene-index">END ${id.slice(-2)}　${title}</span></div><div class="opening-dialogue" data-ending-next role="button" tabindex="0" aria-label="次の台詞へ"><div class="speaker">${speaker?escapeHtml(speaker):'演出'}</div><div class="line ${speaker?'':'ending-cue'}" id="ending-line">${escapeHtml(full.slice(0,result.shown||0))}</div><div class="prompt">クリック / タップで進む ▸</div></div></div></div>`;
  fitNovelStage();
  startEndingTyping(full);
 }else{
  screen.innerHTML=`<div class="opening-frame ending-result-fade"><div class="opening-art loaded">${stillUrl?`<img class="opening-still-img" src="${escapeHtml(stillUrl)}" alt="" decoding="sync">`:''}</div><div class="opening-stage ending-stage"><div class="ending-result"><div class="overline">END ${id.slice(-2)} · FINAL RESULT</div><h2>${title}</h2><p>${escapeHtml(ENDING_SCRIPTS[id].description)}</p><p>90日間の累計売上：${fmt(result.sales??state.sales)}</p><p>借金返済総額：${fmt(result.repaid??state.repaid)} ／ 借金残高：${fmt(result.debt)}</p><p>最終所持金：${fmt(result.cash)}</p><p>主要設備：${result.equipmentCount??ENDING_GOALS.majorEquipment.filter(key=>state.equipment[key]).length} / 3種類</p><p>図鑑登録：${result.codexCount} / ${PRODUCTS.length}種類</p><p>達成評価：${title}</p>${resultAnalyticsHtml()}<div class="actions"><button class="btn" data-act="title">タイトルへ</button><button class="btn" data-act="restart">もう一度遊ぶ</button><button class="btn" data-act="ending-replay">エンディングを再視聴</button></div></div></div></div>`;
  fitNovelStage();
 }
}
let endingTypingTimer=null;
function clearEndingTyping(){if(endingTypingTimer){window.clearInterval(endingTypingTimer);endingTypingTimer=null;}}
function startEndingTyping(full){clearEndingTyping();const result=state.ending;if(result.shown>=full.length)return;endingTypingTimer=window.setInterval(()=>{if(state.ending!==result||result.stage!=='still'){clearEndingTyping();return;}result.shown=Math.min(full.length,(result.shown||0)+2);const line=$('#ending-line');if(line)line.textContent=full.slice(0,result.shown);if(result.shown>=full.length)clearEndingTyping();},24);}
function endingAdvance(){if(!state.finished||state.ending?.stage!=='still')return;const r=state.ending,script=ENDING_SCRIPTS[r.id],raw=script.lines[r.line||0][1],full=raw.replace('{debt}',Math.round(r.debt).toLocaleString('ja-JP'));if((r.shown||0)<full.length){r.shown=full.length;clearEndingTyping();const line=$('#ending-line');if(line)line.textContent=full;playSE('dialogue');return;}clearEndingTyping();r.line=(r.line||0)+1;r.shown=0;if(r.line>=script.lines.length){r.stage='result';playSE('page');}else{playSE('dialogue');}save();showEnding();}
function replayEnding(){if(!state.finished||!state.ending)return;clearEndingTyping();state.ending.stage='still';state.ending.line=0;state.ending.shown=0;BGM.play(state.ending.id,{restart:true});showEnding();}
function restart(){return startNewFromTitle();}
let titleCodexActive=false,titleCodexReturnTab='shop',titleMenuBusy=false;
function fitTitleStage(){fitImagePlate($('.title-image-frame'),$('.title-image-stage'),1920,1080);}
window.addEventListener?.('resize',fitTitleStage);
function titlePanel(kind,message=''){
 const bgm=BGM.getSettings();
 const se=typeof SE!=='undefined'?SE.getSettings():{volume:75,muted:!!state.muted};
 const contents=kind==='settings'?'<h2>設定</h2><p>効果音（SE）</p><button data-title-act="sound" class="title-panel-action">効果音 '+(state.muted?'OFF':'ON')+'</button><p><label for="se-volume">効果音音量：<span id="se-volume-label">'+se.volume+'</span>％</label></p><input id="se-volume" aria-label="効果音音量" type="range" min="0" max="100" step="1" value="'+se.volume+'" style="width:75%;accent-color:#cda85d"><p>BGM</p><button data-title-act="bgm-toggle" class="title-panel-action">BGM '+(bgm.enabled?'ON':'OFF')+'</button><p><label for="bgm-volume">BGM音量：<span id="bgm-volume-label">'+bgm.volume+'</span>％</label></p><input id="bgm-volume" aria-label="BGM音量" type="range" min="0" max="100" step="1" value="'+bgm.volume+'" style="width:75%;accent-color:#cda85d"><p class="title-panel-note">音量設定はゲーム進行と別に保存されます。</p>':kind==='confirm-new'?'<h2>最初から始めますか？</h2><p>現在の90日版セーブデータを上書きして、1日目から始めます。</p><button data-title-act="new-confirm" class="title-panel-action primary">上書きして始める</button>':kind==='confirm-exit'?'<h2>ゲームを終了しますか？</h2><p>セーブデータはブラウザに保持されます。</p><button data-title-act="exit-confirm" class="title-panel-action">終了する</button>':kind==='confirm-migrate'?'<h2>旧30日版データを移行しますか？</h2><p>借金残高には40,000 Gが追加され、旧セーブはそのまま保持されます。'+(hasStoredGame?'現在の90日版セーブは上書きされます。':'')+'</p><button data-title-act="migrate-confirm" class="title-panel-action primary">移行して始める</button>':kind==='exit'?'<h2>またのご来店をお待ちしております。</h2><p>セーブデータは保持されています。</p>':'<h2>セーブデータを読み込めません</h2><p>'+escapeHtml(message)+'</p>';
 const label=kind==='settings'?'設定':kind==='confirm-new'?'最初から始める確認':kind==='confirm-exit'?'終了確認':kind==='confirm-migrate'?'データ移行確認':kind==='exit'?'終了案内':'読み込みエラー';
 return `<div class="title-overlay-shade"><section class="title-overlay-panel" role="dialog" aria-label="${label}">${contents}<button class="title-panel-action" data-title-act="back">タイトルへ戻る</button></section></div>`;
}
function showTitleScreen(panel=''){BGM.stop();clearAutoTimer();clearOpeningTimer();clearEndingTyping();stopOpeningBgm();openingRun=null;titleCodexActive=false;document.body?.classList?.toggle('title-codex-mode',false);$('#opening').classList.add('hidden');$('#opening').innerHTML='';closeModal();
 const options=[['new','はじめから'],['continue','つづきから'],['codex','図鑑'],['settings','設定'],['exit','終了']];
 $('#title-screen').innerHTML=`<div class="title-image-frame"><div class="title-image-stage" aria-label="タイトル画面">${options.map(([key,label],i)=>`<button class="title-image-hit title-hit-${i+1}" data-title-act="${key}" aria-label="${label}" title="${label}" ${key==='continue'&&!hasStoredGame?'disabled':''}></button>`).join('')}${panel?titlePanel(panel):''}</div></div>`;$('#title-screen').classList.remove('hidden');fitTitleStage();titleMenuBusy=false;if(typeof GUIDE!=='undefined')GUIDE.sync();}
function hideTitleScreen(){$('#title-screen').classList.add('hidden');$('#title-screen').innerHTML='';}
function migrateLegacy(confirmed=false){if(!hasLegacyGame)return;if(!confirmed){showTitleScreen('confirm-migrate');return;}let old;try{old=JSON.parse(localStorage.getItem(LEGACY_KEY));}catch{}if(!old||!Array.isArray(old.inventory))return;const d=newState();d.day=Math.max(1,Math.min(RULES.days,Number(old.day)||1));d.cash=Math.max(0,Number(old.cash)||0);d.repaid=Math.max(0,Number(old.repaid)||0);d.debt=Math.max(0,RULES.debt-d.repaid);d.principal=RULES.debt;d.inventory=old.inventory.filter(x=>product(x.id)&&x.qty>0&&QUALITY[x.quality]);d.equipment.shelf=!!old.equipment?.shelf;d.equipment.sign=!!old.equipment?.sign;d.prices={...d.prices,...old.prices};d.sales=Number(old.sales)||0;d.cogs=Number(old.cogs)||0;d.fees=Number(old.fees)||0;d.expense=(Number(old.expense)||0)+(d.equipment.shelf?500:0);d.log=Array.isArray(old.log)?old.log:[];d.muted=!!old.muted;d.introSeen=true;d.postOpeningStep=2;d.phase='prepare';d.demand=demandInitial(d.day);state=d;refreshMarket(state);save();hideTitleScreen();tab='shop';render();}
function startNewFromTitle(confirmed=false){if(hasStoredGame&&!confirmed){showTitleScreen('confirm-new');return false;}const priorMute=state.muted;state=newState();state.muted=priorMute;hasStoredGame=true;tab='shop';routeId='market';closeModal();hideTitleScreen();if(typeof GUIDE!=='undefined'&&GUIDE.resetForNewGame)GUIDE.resetForNewGame();save();render();beginOpening(false);return true;}
function continueFromTitle(){if(!hasStoredGame)return false;let raw;try{raw=JSON.parse(localStorage.getItem(KEY));}catch{showTitleScreen('error','セーブデータの形式が破損しています。データは削除していません。');return false;}if(!raw||!Array.isArray(raw.inventory)||!raw.market||typeof raw.market!=='object'){showTitleScreen('error','必要な保存項目が不足しています。データは削除していません。');return false;}try{state=load();hideTitleScreen();render();if(!state.introSeen)beginOpening(false);else if(state.finished){if(!state.ending&&state.day===RULES.days&&state.phase==='closed'){state.finished=false;finish();}else showEnding();}else BGM.play('shop');return true;}catch{showTitleScreen('error','セーブデータの読み込み処理でエラーが発生しました。データは削除していません。');return false;}}
function openCodexFromTitle(){if(titleCodexActive)return;titleCodexReturnTab=tab;titleCodexActive=true;clearAutoTimer();hideTitleScreen();tab='codex';codexPage=0;codexListPage=0;render();}
function returnCodexToTitle(){if(!titleCodexActive)return;titleCodexActive=false;tab=titleCodexReturnTab;render();showTitleScreen();}
function confirmTitleExit(confirmed=false){if(!confirmed){showTitleScreen('confirm-exit');return;}showTitleScreen('exit');}
const AFTER_OPENING=[
  'さあ！ 私の華麗なる商人人生の幕開けですわ！',
  '……こほん。まずは商品を仕入れましょうか'
];
let openingRun=null;
let openingBgm=null;
function openingSound(url,loop=false){if(!url||typeof Audio!=='function')return null;try{const audio=new Audio(url);audio.loop=loop;audio.volume=loop?.35:.6;audio.play().catch(()=>{});return audio;}catch{return null;}}
function stopOpeningBgm(){if(openingBgm){openingBgm.pause();openingBgm=null;}}
function openingCue(name){if(!openingRun||openingRun.mode!=='scene')return;const cfg=OPENING_MEDIA[OPENING_SCENES[openingRun.scene].id];if(cfg?.se?.[name]){if(!state.muted)openingSound(cfg.se[name]);return;}const map={fall:'openingFall',market:'openingMarket',paper:'openingPaper',signature:'openingSignature',doorOpen:'openingDoorOpen',doorClose:'openingDoorClose'};if(map[name])playSE(map[name]);}
function clearOpeningTimer(){if(openingRun?.timer){window.clearInterval(openingRun.timer);openingRun.timer=null;}}
function preloadOpeningStills(){if(typeof Image!=='function')return;for(const media of Object.values(OPENING_MEDIA)){if(!media?.image)continue;const img=new Image();img.src=media.image;}}
function beginOpening(replay=false,returnToTitle=false){clearAutoTimer();clearOpeningTimer();stopOpeningBgm();BGM.play('opening',{restart:true});closeModal();preloadOpeningStills();openingRun={replay,returnToTitle,scene:0,line:0,shown:0,mode:'scene',timer:null,transitioning:false};$('#opening').classList.remove('hidden');showOpeningScene();}
function showOpeningScene(){if(!openingRun)return;const run=openingRun,scene=OPENING_SCENES[run.scene],media=OPENING_MEDIA[scene.id];run.transitioning=false;run.mode='scene';run.line=0;
$('#opening').innerHTML=`<div class="opening-frame"><div class="opening-art scene-${run.scene}" data-still="${scene.id}"><img class="opening-still-img" src="${escapeHtml(media.image)}" alt="" decoding="sync" fetchpriority="high"></div><div class="opening-stage"><div class="opening-placeholder"><span class="scene-symbol">${['☼','⚖','⚱','✒'][run.scene]}</span><div class="scene-context">${escapeHtml(media.placeholder)}</div><small>仮背景：${scene.id}</small></div><div class="opening-top"><span class="scene-index">SCENE 0${run.scene+1}　【${scene.act}】${scene.title}</span><button class="btn skip" data-opening-skip>スキップ »</button></div><div class="opening-dialogue" data-opening-next role="button" tabindex="0" aria-label="次の台詞へ"><div class="speaker" id="opening-speaker"></div><div class="line" id="opening-line"></div><div class="prompt">クリック / タップで進む ▸</div></div><div class="opening-fade" id="opening-fade"></div></div></div>`;
  fitNovelStage();
  // Missing art is deliberately non-blocking. The gradient placeholder remains visible.
  const img=$('#opening .opening-still-img'),art=$('#opening .opening-art'),placeholder=$('#opening .opening-placeholder');
  const markLoaded=()=>{if(openingRun===run&&run.mode==='scene'){art?.classList.add('loaded');placeholder?.classList.add('hidden');}};
  if(img){
    if(img.complete&&img.naturalWidth>0)markLoaded();
    else{
      img.onload=markLoaded;
      img.onerror=()=>{img.hidden=true;};
    }
  }
  // The entire opening uses one non-looping track; scene transitions never restart it.
  if(run.scene===0){const fade=$('#opening-fade');fade.style.background='#f5f4eb';fade.classList.add('visible');window.setTimeout(()=>{if(openingRun===run)fade.classList.remove('visible');},80);}
  if(run.scene===1)openingCue('market');if(run.scene===2)openingCue('paper');if(run.scene===3)openingCue('doorOpen');
  showOpeningLine();
}
function showOpeningLine(){clearOpeningTimer();if(!openingRun||openingRun.mode!=='scene')return;const [speaker,text]=OPENING_SCENES[openingRun.scene].lines[openingRun.line];$('#opening-speaker').textContent=speaker;const el=$('#opening-line');el.textContent='';openingRun.shown=0;
  const run=openingRun;run.timer=window.setInterval(()=>{if(openingRun!==run){clearOpeningTimer();return;}run.shown=Math.min(text.length,run.shown+2);el.textContent=text.slice(0,run.shown);if(run.shown>=text.length)clearOpeningTimer();},24);
}
function openingAdvance(){const run=openingRun;if(!run||run.transitioning)return;if(run.mode==='title'){playSE('openShop');finishOpening();return;}const lines=OPENING_SCENES[run.scene].lines;const full=lines[run.line][1];if(run.shown<full.length){clearOpeningTimer();run.shown=full.length;$('#opening-line').textContent=full;playSE('dialogue');return;}
  if(run.line<lines.length-1){run.line++;playSE('dialogue');showOpeningLine();return;}
  if(run.scene===0)openingCue('fall');else if(run.scene===2)openingCue('signature');else if(run.scene===3)openingCue('doorClose');else playSE('dialogue');
  run.transitioning=true;clearOpeningTimer();$('#opening-fade')?.classList.add('visible');window.setTimeout(()=>{if(openingRun!==run)return;if(run.scene<OPENING_SCENES.length-1){run.scene++;showOpeningScene();}else showOpeningTitle();},260);
}
function showOpeningTitle(){if(!openingRun)return;openingRun.mode='title';openingRun.transitioning=false;$('#opening').innerHTML=`<div class="opening-frame"><div class="opening-title" data-opening-next role="button" tabindex="0" aria-label="店舗へ進む"><div class="overline">THE ANGEL'S CURIO CABINET</div><h2>天使の珍品商</h2><p>90日以内に、借金45,000 Gを返済せよ。</p><div class="entry-prompt">クリック・タップで店舗へ ▸</div><button class="btn skip" data-opening-skip>スキップして店舗へ</button></div></div>`;fitNovelStage();}
function finishOpening(skipped=false){if(!openingRun)return;const {replay,returnToTitle}=openingRun;clearOpeningTimer();stopOpeningBgm();openingRun=null;$('#opening').classList.add('hidden');$('#opening').innerHTML='';if(returnToTitle){showTitleScreen();return;}BGM.play('shop');if(!replay){state.introSeen=true;state.postOpeningStep=2;state.dialogue=skipped?{key:'prepare',text:SPEECH.prepare[0],mood:'proud'}:{key:'intro',text:AFTER_OPENING[1],mood:'proud'};save();tab='shop';render();if(typeof GUIDE!=='undefined')GUIDE.maybeOpenFirstTime();}else render();}
function nextIntroLine(){if(!state.introSeen||state.postOpeningStep>=2)return;state.postOpeningStep++;if(state.postOpeningStep===1)state.dialogue={key:'intro',text:AFTER_OPENING[1],mood:'surprised'};else state.dialogue={key:'prepare',text:AFTER_OPENING[1],mood:'proud'};playSE('dialogue');save();render();}
document.addEventListener('click',e=>{if(!openingRun)return;if(e.target.closest('[data-opening-skip]')){playSE('ui');finishOpening(true);return;}if(e.target.closest('[data-opening-next]'))openingAdvance();});
document.addEventListener('click',e=>{if(e.target.closest?.('[data-ending-next]'))endingAdvance();});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.closest?.('[data-ending-next]')){e.preventDefault();endingAdvance();}});
document.addEventListener('keydown',e=>{if(!openingRun)return;if(e.key==='Enter'||e.key===' '){if(e.target.closest('[data-opening-next]')){e.preventDefault();openingAdvance();}}});
// Only linear dialogue advances from the parchment. Choices and transaction buttons keep their own actions.
function advanceParchment(kind){if(openingRun)return;if(kind==='debt'&&state.debtCelebration)advanceDebtCelebration();else if(kind==='intro'&&state.introSeen&&state.postOpeningStep<2&&!state.activeEvent)nextIntroLine();else if(kind==='normal'&&state.activeEvent&&NORMAL_EVENTS[state.activeEvent.id]&&state.activeEvent.stage!=='choice')normalEventNext();else if(kind==='story'&&state.activeEvent&&!NORMAL_EVENTS[state.activeEvent.id]&&state.activeEvent.stage!=='choice')storyEventNext();}
let parchmentPointer=null;
document.addEventListener('pointerdown',e=>{parchmentPointer=e.target.closest?.('[data-dialogue-advance]')?{x:e.clientX,y:e.clientY}:null;});
document.addEventListener('click',e=>{const pane=e.target.closest?.('[data-dialogue-advance]');if(!pane||e.target.closest('button,a,input,select,textarea,[contenteditable="true"]'))return;if(parchmentPointer&&Math.hypot(e.clientX-parchmentPointer.x,e.clientY-parchmentPointer.y)>8)return;parchmentPointer=null;advanceParchment(pane.dataset.dialogueAdvance);});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('[data-dialogue-advance]')){e.preventDefault();advanceParchment(e.target.dataset.dialogueAdvance);}});
document.addEventListener('click',e=>{BGM.retry();if(typeof SE!=='undefined')SE.unlock();const b=e.target.closest?.('button');if(!b)return;if(b.dataset.titleAct){e.stopImmediatePropagation();if(b.disabled||titleMenuBusy)return;titleMenuBusy=true;try{const act=b.dataset.titleAct;if(act==='new'){playSE('ui');startNewFromTitle();}else if(act==='new-confirm'){playSE('ui');startNewFromTitle(true);}else if(act==='continue'){playSE('openShop');continueFromTitle();}else if(act==='codex'){playSE('page');openCodexFromTitle();}else if(act==='settings'){playSE('ui');showTitleScreen('settings');}else if(act==='exit'){playSE('ui');confirmTitleExit();}else if(act==='exit-confirm'){playSE('ui');confirmTitleExit(true);}else if(act==='back'){playSE('ui');showTitleScreen();}else if(act==='sound'){state.muted=!state.muted;if(hasStoredGame)save();showTitleScreen('settings');if(!state.muted)playSE('sell');}else if(act==='bgm-toggle'){BGM.setEnabled(!BGM.getSettings().enabled);playSE('ui');showTitleScreen('settings');}else if(act==='watch'){playSE('ui');hideTitleScreen();beginOpening(true,true);}else if(act==='migrate'){playSE('ui');migrateLegacy();}else if(act==='migrate-confirm'){playSE('ui');migrateLegacy(true);}}finally{titleMenuBusy=false;}return;}if(b.hasAttribute('data-title-codex-return')){e.stopImmediatePropagation();playSE('page');returnCodexToTitle();return;}if(titleCodexActive&&!b.hasAttribute('data-codex-page')&&!b.hasAttribute('data-codex-list'))e.stopImmediatePropagation();});
document.addEventListener('input',e=>{if(e.target?.id==='bgm-volume'){BGM.setVolume(e.target.value);const label=$('#bgm-volume-label');if(label)label.textContent=BGM.getSettings().volume;}else if(e.target?.id==='se-volume'&&typeof SE!=='undefined'){SE.setVolume(e.target.value);const label=$('#se-volume-label');if(label)label.textContent=SE.getSettings().volume;}});
document.addEventListener('change',e=>{if(e.target?.id==='se-volume'&&typeof SE!=='undefined'){SE.setVolume(e.target.value);playSE('sell');return;}if(!e.target?.matches?.('[data-bulk-mode]'))return;const mode=e.target.value;if(!['recommended','profit','clearance'].includes(mode)||state.finished)return;state.bulkDisplayMode=mode;bulkDisplayNotice='';playSE('ui');save();render();});
document.addEventListener('click',e=>{const button=e.target.closest?.('button[data-display-all]');if(button&&!button.disabled)replenishSameProduct(button.dataset.displayAll);});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b){if(e.target.id==='modal'){playSE('modalClose');closeModal();}return;}if(b.disabled)return;if(b.dataset.titleAct){if(b.dataset.titleAct==='new')startNewFromTitle();if(b.dataset.titleAct==='new-confirm')startNewFromTitle(true);if(b.dataset.titleAct==='continue')continueFromTitle();if(b.dataset.titleAct==='watch'){hideTitleScreen();beginOpening(true,true);}if(b.dataset.titleAct==='migrate')migrateLegacy();if(b.dataset.titleAct==='migrate-confirm')migrateLegacy(true);return;}if(b.dataset.act==='guide'&&typeof GUIDE!=='undefined'){playSE('ui');GUIDE.open();return;}if(b.dataset.act==='title'){playSE('ui');showTitleScreen();return;}if(openingRun)return;if(state.activeEvent){if(b.hasAttribute('data-normal-next'))normalEventNext();else if(b.dataset.normalChoice)normalEventChoose(b.dataset.normalChoice);else if(b.hasAttribute('data-story-next'))storyEventNext();else if(b.dataset.storyChoice)storyEventChoose(b.dataset.storyChoice);return;}if(b.dataset.ledgerMode){ledgerMode=b.dataset.ledgerMode;ledgerDetail=null;playSE('page');render();return;}if(b.dataset.ledgerCat){ledgerEquipCategory=b.dataset.ledgerCat;ledgerDetail=null;playSE('page');render();return;}if(b.dataset.ledgerRange){ledgerGraphRange=b.dataset.ledgerRange==='all'?'all':Number(b.dataset.ledgerRange);playSE('ui');render();return;}if(b.dataset.ledgerDetail){ledgerDetail=b.dataset.ledgerDetail;playSE('modalOpen');render();return;}if(b.hasAttribute('data-ledger-detail-close')){ledgerDetail=null;playSE('modalClose');render();return;}if(b.dataset.warning){state.warningDismissed=`${state.day}:${state.phase}`;if(b.dataset.warning==='market')tab='market';if(b.dataset.warning==='shop')tab='shop';playSE('ui');save();render();return;}if(state.introSeen&&state.postOpeningStep<2){if(b.dataset.act==='intro-next')nextIntroLine();return;}if(b.dataset.tab){if(state.phase==='serving'&&b.dataset.tab!=='shop'&&state.service?.stage!=='reaction')return;closeModal();tab=b.dataset.tab;playSE(tab==='codex'||tab==='ledger'?'page':'ui');render();return;}if(b.dataset.speed){setSpeed(b.dataset.speed);return;}if(b.hasAttribute('data-auto-pause')){toggleAutoPause();return;}if(b.dataset.buyQty){const key=`${routeId}:${b.dataset.buyQty}`;buyAmounts[key]=Math.max(1,Math.min(10,purchaseQuantity(b.dataset.buyQty)+Number(b.dataset.delta)));playSE('ui');render();return;}if(b.dataset.buyMany){buyMany(b.dataset.buyMany,purchaseQuantity(b.dataset.buyMany));return;}if(b.dataset.display){changeDisplay(b.dataset.display,Number(b.dataset.delta));return;}if(b.dataset.locked){showLockedModal(b.dataset.locked);return;}if(b.dataset.shelfChoose!==undefined){showShelfChooser(Number(b.dataset.shelfChoose));return;}if(b.dataset.shelfAssign!==undefined){assignShelfSlot(Number(b.dataset.shelfAssign),b.dataset.shelfProduct);return;}if(b.dataset.marketPage){marketPage=Math.max(0,marketPage+Number(b.dataset.marketPage));playSE('page');render();return;}if(b.dataset.route){routeId=b.dataset.route;marketPage=0;playSE('page');render();return;}if(b.dataset.unlockRoute){unlockRoute(b.dataset.unlockRoute);return;}if(b.dataset.select){showProductModal(b.dataset.select);return;}if(b.dataset.buy){buy(b.dataset.buy);return;}if(b.dataset.appraise!==undefined){appraise(Number(b.dataset.appraise));return;}if(b.dataset.price){setPrice(state.prices[selected]+Number(b.dataset.price));return;}if(b.dataset.equip){equip(b.dataset.equip);return;}
  switch(b.dataset.act){case'close':playSE('modalClose');closeModal();break;case'undisplayed-choose':showUndisplayedChooser();break;case'undisplayed-dismiss':playSE('ui');state.undisplayedNoticeDismissed=undisplayedSignature();save();render();break;case'demand-details':showDemandDetails();break;case'special-order':showSpecialOrderModal();break;case'deliver-order':deliverSpecialOrder();break;case'negotiate':negotiateOffer();break;case'upsell':acceptUpsell();break;case'final-repay':finalRepay();break;case'final-confirm':finish();break;case'final-confirm-yes':finish(true);break;case'bulk-display':bulkDisplay();break;case'setprice':setPrice($('#sell-price').value);break;case'open':openShop();break;case'sell':sell();break;case'decline':decline();break;case'advance':advance();break;case'fastforward':fastForward();break;case'fastforward-confirm':fastForward(true);break;case'next':nextDay();break;case'report':showReportModal();break;case'replay':playSE('ui');beginOpening(true);break;case'title':playSE('ui');showTitleScreen();break;case'repay':repay(100);break;case'repayall':repay(state.cash);break;case'mute':state.muted=!state.muted;save();render();if(!state.muted)playSE('sell');break;case'restart':playSE('ui');restart();break;case'ending-replay':playSE('ui');replayEnding();break;case'free':playSE('openShop');state.finished=false;state.free=true;state.phase='closed';state.service=null;closeModal();save();render();break;}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').classList.contains('hidden')){playSE('modalClose');closeModal();}if(e.key==='Enter'&&e.target.id==='sell-price')setPrice(e.target.value);});
// Page turns are view-only; they never touch inventory, money, codex flags or saves.
document.addEventListener('click',e=>{const button=e.target.closest?.('button[data-codex-page]');if(!button||tab!=='codex'||state.activeEvent||button.disabled)return;const direction=button.dataset.codexPage;codexPage=direction==='prev'?codexPage-1:direction==='next'?codexPage+1:Number(direction);codexPage=Math.max(0,Math.min(PRODUCTS.length-1,codexPage));codexListPage=codexPage<14?0:1;updateCodexPage();});
// Optional asset slots: missing images never interrupt gameplay, while new PNG files take over automatically.
document.addEventListener('click',e=>{const button=e.target.closest?.('button[data-codex-list]');if(!button||tab!=='codex'||state.activeEvent||button.disabled)return;codexListPage=Math.max(0,Math.min(1,codexListPage+(button.dataset.codexList==='next'?1:-1)));codexPage=codexListPage*14;updateCodexPage();});
document.addEventListener('error',e=>{if(e.target.matches?.('[data-optional-image]')){e.target.hidden=true;if(e.target.parentElement?.classList.contains('story-still-overlay'))e.target.parentElement.hidden=true;if(e.target.classList.contains('customer-portrait-image'))e.target.parentElement?.classList.remove('has-portrait-slot');}},true);
document.addEventListener('load',e=>{if(e.target.matches?.('[data-optional-image]'))e.target.parentElement?.classList.add('has-art');},true);
// The opening, event novels, endings and results share the same scaled plate.
// A transform preserves artwork coordinates and hit targets even at browser zoom.
function fitNovelStage(){const layer=$('#opening');if(!layer)return;const frame=layer.querySelector('.opening-frame'),stage=layer.querySelector('.opening-stage,.opening-title');if(!stage)return;const width=layer.clientWidth||window.innerWidth||1920,height=layer.clientHeight||window.innerHeight||1080;const fit=Math.min(width/1920,height/1080),scale=Math.max(.01,width<900||height<570?Math.max(.55,fit):fit);if(frame){frame.style.width=`${Math.round(1920*scale)}px`;frame.style.height=`${Math.round(1080*scale)}px`;}stage.style.transform=`scale(${scale})`;}
if(typeof MutationObserver!=='undefined')new MutationObserver(fitNovelStage).observe($('#opening'),{childList:true});
window.addEventListener?.('resize',fitNovelStage);
window.visualViewport?.addEventListener?.('resize',fitNovelStage);
render();showTitleScreen();
